from .graph import DEPENDENCIES
def build_plan(roots):
    ordered, visited = [], set()
    def visit(name):
        if name in visited:
            return
        for dependency in DEPENDENCIES[name]:
            visit(dependency)
        visited.add(name)
        ordered.append(name)
    for root in roots:
        visit(root)
    return ordered

